	@Test
	void samplesLogicalDuplicateMassWithBoundedPageReads(@TempDir Path tempDir) throws Exception {
		int leafCount = 160;
		long[] multiplicities = new long[leafCount];
		long totalEntries = 0;
		for (int leaf = 0; leaf < leafCount; leaf++) {
			// Deliberately non-uniform and locally clustered. The range sampler must weight sampled leaves by logical
			// duplicate mass rather than by the number of outer keys.
			long multiplicity = 1L + (leaf % 11);
			if (leaf >= 48 && leaf < 64) {
				multiplicity += 40;
			}
			multiplicities[leaf] = multiplicity;
			totalEntries += multiplicity;
		}
		TreeFile tree = writeSingleBranchDupSortTree(tempDir.resolve("data.mdb"), multiplicities);
		long expected = totalEntries - multiplicities[0] - multiplicities[leafCount - 1];

		RangeCountResult first = count(tree, statementKey(1), statementKey(leafCount - 2), null);
		RangeCountResult second = count(tree, statementKey(1), statementKey(leafCount - 2), null);
		double relativeError = Math.abs(first.entries - expected) / (double) expected;

		assertEquals(first.entries, second.entries, "The same logical range must select the same DUPSORT probes");
		assertTrue(relativeError < 0.10,
				() -> "Expected less than 10% error, actual=" + expected + ", estimate=" + first.entries);
		assertTrue(first.leafPagesRead <= 66,
				() -> "Expected at most two boundary leaves plus 64 DUPSORT probes, read " + first.leafPagesRead);
		assertEquals(1, first.branchPagesRead, "The root branch page should be shared by every probe");
	}

